script:
(function () {
  'use strict';
  // CD interest rate <-> APY using the Truth in Savings method (Regulation DD, 12 CFR 1030,
  // Appendix A, Part I.A; rounding to 0.01% per 1030.3(f)(1); both read on eCFR in this session):
  //   APY = 100 x [(1 + Interest / Principal)^(365 / Days in term) - 1]
  // Interest for the term: compounding n times a year over p periods = P x ((1 + r/n)^p - 1),
  //   where p = days for daily compounding, months x n / 12 for a term in months, days x n / 365
  //   otherwise; simple interest = P x r x days / 365.
  // APY to rate: growth G = (1 + APY)^(days/365); r = n x (G^(1/p) - 1), simple r = (G - 1) x 365 / days.
  // Verified (scratchpad cu5/tests/ay.test.js): Reg DD example 2 ($30.37 on $1,000, 182 days) = 6.18%;
  // example 1 ($61.68 on $1,000, 365 days) = 6.17%; 5% compounded daily over 365 days = APY 5.13%
  // ($512.67 on $10,000); 4.5% monthly for 12 months = APY 4.59%; APY -> rate -> APY round trip;
  // 0% rate gives 0 interest; simple 6% for 24 months gives APY 5.83% (Part I.E lets the bank show 6.00%).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var plain = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var FREQS = [[365, 'Daily'], [12, 'Monthly'], [4, 'Quarterly'], [2, 'Semiannually'], [1, 'Annually'], [0, 'None (simple)']];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function pct(x, d) { return (x * 100).toFixed(d) + '%'; }

  function periodsIn(n, unit, months, days) {
    if (n === 0) return 0;
    if (n === 365) return days;
    return unit === 'months' ? months * n / 12 : days * n / 365;
  }
  // Growth factor of $1 over the term at nominal rate r.
  function growth(r, n, p, days) {
    return n === 0 ? 1 + r * days / 365 : Math.pow(1 + r / n, p);
  }
  function tisApy(g, days) { return Math.pow(g, 365 / days) - 1; }
  function rateFromApy(apy, n, p, days) {
    var g = Math.pow(1 + apy, days / 365);
    return n === 0 ? (g - 1) * 365 / days : n * (Math.pow(g, 1 / p) - 1);
  }

  function clear() {
    ['ayOut', 'ayInterest', 'ayBalance', 'ayPeriod', 'ayDaysOut', 'ayPeriodsOut', 'ayPerRate', 'ayTermYield', 'ayFormula'].forEach(function (id) { set(id, '–'); });
    set('ayNote', '');
    document.getElementById('ayTable').innerHTML = '';
  }

  function update() {
    var mode = document.getElementById('ayMode').value, unit = document.getElementById('ayUnit').value,
        n = parseInt(document.getElementById('ayCompound').value, 10),
        deposit = num('ayDeposit'), rate = num('ayRate'), term = num('ayTerm'), daysIn = document.getElementById('ayDays').value.trim();
    set('ayRateLabel', mode === 'apy' ? 'Annual percentage yield (APY)' : 'Interest rate');
    set('ayRateHint', mode === 'apy' ? 'The APY the bank quotes; the calculator finds the interest rate behind it.' : 'The stated (nominal) annual rate before compounding.');
    var error = document.getElementById('ayError');
    var override = daysIn === '' ? NaN : Math.round(parseFloat(daysIn));
    var bad = [deposit, rate, term].some(isNaN) || isNaN(n) || deposit < 0 || deposit > 1e12 || rate < 0 || rate > 100 ||
              term < 1 || (unit === 'months' ? term > 120 : term > 3650) || (daysIn !== '' && (isNaN(override) || override < 1 || override > 3660));
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a deposit of $0 or more, a rate from 0 to 100%, a term of 1 to 120 months (or 1 to 3,650 days) and, if used, 1 to 3,660 days in the term.';
      clear();
      return;
    }
    var months = unit === 'months' ? Math.round(term) : term * 12 / 365;
    var days = unit === 'days' ? Math.round(term) : (daysIn !== '' ? override : Math.round(months * 365 / 12));
    if (unit === 'days') months = days * 12 / 365;
    var p = periodsIn(n, unit, months, days);
    var r, g, apy;
    if (mode === 'apy') {
      apy = rate / 100;
      r = rateFromApy(apy, n, p, days);
      g = Math.pow(1 + apy, days / 365);
    } else {
      r = rate / 100;
      g = growth(r, n, p, days);
      apy = tisApy(g, days);
    }
    var interest = deposit * (g - 1);
    set('ayOutLabel', mode === 'apy' ? 'Interest rate (nominal)' : 'APY (Truth in Savings)');
    set('ayOut', mode === 'apy' ? pct(r, 3) : pct(apy, 2));
    set('ayInterest', money.format(interest));
    set('ayBalance', money.format(deposit + interest));
    if (n === 0) {
      set('ayPeriodLabel', 'Interest per year (not compounded)');
      set('ayPeriod', money.format(deposit * r));
      set('ayPeriodsOut', 'None');
      set('ayPerRate', '–');
    } else {
      set('ayPeriodLabel', 'Interest in the first compounding period');
      set('ayPeriod', money.format(deposit * r / n));
      set('ayPeriodsOut', Math.abs(p - Math.round(p)) < 1e-9 ? String(Math.round(p)) : p.toFixed(2));
      set('ayPerRate', pct(r / n, 5));
    }
    set('ayDaysOut', String(days));
    set('ayTermYield', pct(g - 1, 3));
    var basis = deposit > 0 ? deposit : 1000;
    set('ayFormula', 'APY = 100 × [(1 + ' + plain.format(basis * (g - 1)) + ' ÷ ' + plain.format(basis) + ')^(365 ÷ ' + days + ') − 1] = ' + pct(apy, 2));
    var note = 'Banks round the disclosed APY to the nearest 0.01% (12 CFR 1030.3(f)). Credit unions follow the same formula under NCUA Part 707.';
    if (n === 0 && days > 365) note = 'Simple interest over more than a year gives a lower APY than the rate. If the CD pays the interest out at least once a year, Regulation DD lets the bank disclose the APY as equal to the interest rate (' + pct(r, 2) + ').';
    set('ayNote', note);
    var rows = FREQS.map(function (f) {
      var fn = f[0], fp = periodsIn(fn, unit, months, days), fr, fg;
      if (mode === 'apy') { fr = rateFromApy(apy, fn, fp, days); fg = g; }
      else { fr = r; fg = growth(r, fn, fp, days); }
      var mark = fn === n ? ' (selected)' : '';
      return '<tr><td>' + f[1] + mark + '</td><td>' + pct(fr, 3) + '</td><td>' + pct(tisApy(fg, days), 2) + '</td><td>' + money.format(deposit * (fg - 1)) + '</td></tr>';
    });
    set('ayTableIntro', mode === 'apy' ? 'The interest rate each compounding frequency needs to pay the same APY.' : 'How the APY and interest change if only the compounding frequency changes.');
    document.getElementById('ayTable').innerHTML = rows.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ayForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
